*The Knights assemble in formation*

We are the Knights Who Say NI, and we demand... **COMPREHENSIVE TEST COVERAGE!** Bring us a shrubbery of tests, or we shall say NI to your pull request until you do!

```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { axe, toHaveNoViolations } from 'jest-axe';

expect.extend(toHaveNoViolations);

// NI! Mock the sacred contexts!
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [{ id: '1', name: 'Holy Grail', price: 99.99 }];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 99.99, clearCart: mockClearCart })
}));
vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - The Sacred Shrubbery of Tests', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'NI-12345' });
  });

  // SHRUBBERY THE FIRST: Happy Path!
  it('completes full checkout flow - the path that is not forbidden!', async () => {
    const onComplete = vi.fn();
    render(<Checkout onComplete={onComplete} />);

    // Shipping - Arrange, Act, Assert... or NI!
    await user.type(screen.getByLabelText(/street/i), '123 Ni Lane');
    await user.type(screen.getByLabelText(/city/i), 'Camelot');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip/i), '12345');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Sir Robin');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review & Submit
    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByText(/NI-12345/)).toBeInTheDocument();
    });
    expect(onComplete).toHaveBeenCalledWith('NI-12345');
  });

  // SHRUBBERY THE SECOND: Validation!
  it('displays errors for invalid ZIP - you must bring us... a VALID format!', async () => {
    render(<Checkout />);
    await user.type(screen.getByLabelText(/zip/i), 'NI!');
    await user.click(screen.getByRole('button', { name: /continue/i }));

    expect(screen.getByRole('alert')).toHaveTextContent(/valid zip/i);
  });

  // SHRUBBERY THE THIRD: Empty Cart Edge Case!
  it('shows empty cart message - the cart that says... nothing!', async () => {
    vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
    render(<Checkout />);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });

  // SHRUBBERY THE FOURTH: Payment Failure!
  it('displays payment error and allows retry - NI to failed payments!', async () => {
    mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
    // ... complete shipping/payment steps ...
    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });

  // SHRUBBERY THE FIFTH: Accessibility!
  it('has no accessibility violations - we demand WCAG compliance!', async () => {
    const { container } = render(<Checkout />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
```

